CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,plan text NOT NULL DEFAULT 'community',stripe_customer_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,external_subject text NOT NULL,email text,role text NOT NULL DEFAULT 'member',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,external_subject));
CREATE TABLE search_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE SET NULL,name text NOT NULL,profile_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,source text NOT NULL,source_url text,title text NOT NULL,company text NOT NULL,description text NOT NULL,location text,rate_min int,rate_max int,c2c_status text NOT NULL,fit_score int NOT NULL,status text NOT NULL DEFAULT 'new',screening_json jsonb NOT NULL,fingerprint text GENERATED ALWAYS AS (encode(digest(lower(company||'|'||title||'|'||coalesce(source_url,'')),'sha256'),'hex')) STORED,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,fingerprint));
CREATE TABLE agent_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),trace_id text NOT NULL,operation text NOT NULL,status text NOT NULL,graph_version text,prompt_version text,model text,input_tokens int NOT NULL DEFAULT 0,output_tokens int NOT NULL DEFAULT 0,estimated_cost_usd numeric(12,6) NOT NULL DEFAULT 0,actual_cost_usd numeric(12,6),latency_ms numeric(12,2),policy_decisions jsonb NOT NULL DEFAULT '[]',evaluation_json jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE budget_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,usage_date date NOT NULL,reserved_usd numeric(12,6) NOT NULL,actual_usd numeric(12,6),input_tokens int NOT NULL DEFAULT 0,output_tokens int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'reserved',created_at timestamptz NOT NULL DEFAULT now(),reconciled_at timestamptz);
CREATE TABLE webhook_events(id text PRIMARY KEY,tenant_id uuid REFERENCES tenants(id) ON DELETE CASCADE,provider text NOT NULL,event_type text NOT NULL,payload_sha256 text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_jobs_tenant_score ON jobs(tenant_id,fit_score DESC,created_at DESC);
CREATE INDEX idx_jobs_tenant_status ON jobs(tenant_id,status,updated_at DESC);
CREATE INDEX idx_runs_tenant_created ON agent_runs(tenant_id,created_at DESC);
CREATE INDEX idx_budget_tenant_date ON budget_reservations(tenant_id,usage_date);
ALTER TABLE users ENABLE ROW LEVEL SECURITY; ALTER TABLE search_profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE jobs ENABLE ROW LEVEL SECURITY; ALTER TABLE agent_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE budget_reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_users ON users USING(tenant_id::text=current_setting('app.tenant_id',true));
CREATE POLICY tenant_profiles ON search_profiles USING(tenant_id::text=current_setting('app.tenant_id',true));
CREATE POLICY tenant_jobs ON jobs USING(tenant_id::text=current_setting('app.tenant_id',true));
CREATE POLICY tenant_runs ON agent_runs USING(tenant_id::text=current_setting('app.tenant_id',true));
CREATE POLICY tenant_budgets ON budget_reservations USING(tenant_id::text=current_setting('app.tenant_id',true));
CREATE OR REPLACE FUNCTION reserve_ai_budget(p_tenant uuid,p_date date,p_amount numeric,p_limit numeric) RETURNS TABLE(id uuid,reserved_usd numeric) LANGUAGE plpgsql AS $$ DECLARE total numeric; new_id uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_tenant::text||p_date::text)); SELECT coalesce(sum(coalesce(actual_usd,reserved_usd)),0) INTO total FROM budget_reservations WHERE tenant_id=p_tenant AND usage_date=p_date AND status IN('reserved','reconciled'); IF total+p_amount>p_limit THEN RETURN; END IF; INSERT INTO budget_reservations(tenant_id,usage_date,reserved_usd) VALUES(p_tenant,p_date,p_amount) RETURNING budget_reservations.id INTO new_id; RETURN QUERY SELECT new_id,p_amount; END $$;
CREATE OR REPLACE FUNCTION reconcile_ai_budget(p_tenant uuid,p_id uuid,p_actual numeric,p_input int,p_output int) RETURNS void LANGUAGE plpgsql AS $$ BEGIN UPDATE budget_reservations SET actual_usd=p_actual,input_tokens=p_input,output_tokens=p_output,status='reconciled',reconciled_at=now() WHERE tenant_id=p_tenant AND id=p_id AND status='reserved'; END $$;
